// #Sireum

package scp_candidate.Mining_Threat_Retreat_Supervisor

import org.sireum._
import art.Art
import scp_candidate._

// Do not edit this file as it will be overwritten if HAMR codegen is rerun
@msig trait Fault_Assessment_supervisor_fa_TestApi {

  def BeforeEntrypoint(): Unit = {
    Art.initTest(Arch.Mining_Threat_Retreat_Supervisor_Root_Instance_supervisor_fa)
  }

  def AfterEntrypoint(): Unit = {
    Art.finalizeTest(Arch.Mining_Threat_Retreat_Supervisor_Root_Instance_supervisor_fa)
  }

  def testCompute(): Unit = {
    Art.manuallyClearOutput()
    Art.testCompute(Arch.Mining_Threat_Retreat_Supervisor_Root_Instance_supervisor_fa)
  }

  def testInitialise(): Unit = {
    Art.manuallyClearOutput()
    Art.testInitialise(Arch.Mining_Threat_Retreat_Supervisor_Root_Instance_supervisor_fa)
  }

  /** helper function to set the values of all input ports.
   * @param mission_invalidity payload for data port mission_invalidity
   * @param threat_invalidity payload for data port threat_invalidity
   * @param resource_invalidity payload for data port resource_invalidity
   * @param phase_context payload for data port phase_context
   */
  def put_concrete_inputs(mission_invalidity : Mining_Threat_Retreat_Supervisor.Mission_Invalidity_Facts,
                          threat_invalidity : Mining_Threat_Retreat_Supervisor.Threat_Invalidity,
                          resource_invalidity : Mining_Threat_Retreat_Supervisor.Resource_Invalidity,
                          phase_context : Mining_Threat_Retreat_Supervisor.Phase_Context): Unit = {
    put_mission_invalidity(mission_invalidity)
    put_threat_invalidity(threat_invalidity)
    put_resource_invalidity(resource_invalidity)
    put_phase_context(phase_context)
  }


  /** helper function to check Fault_Assessment_supervisor_fa's
   * output ports.  Use named arguments to check subsets of the output ports.
   * @param fault method that will be called with the value of the outgoing data
   *        port 'fault'.
   */
  def check_concrete_output(fault: Mining_Threat_Retreat_Supervisor.Fault_Fact => B): Unit = {
    var testFailures: ISZ[ST] = ISZ()

    val faultValue: Mining_Threat_Retreat_Supervisor.Fault_Fact = get_fault().get
    if(!fault(faultValue)) {
      testFailures = testFailures :+ st"'fault' did not match expected: value of the outgoing data port is ${faultValue}"
    }

    assert(testFailures.isEmpty, st"${(testFailures, "\n")}".render)
  }


  // setter for in DataPort
  def put_mission_invalidity(value : Mining_Threat_Retreat_Supervisor.Mission_Invalidity_Facts): Unit = {
    Art.insertInInfrastructurePort(Arch.Mining_Threat_Retreat_Supervisor_Root_Instance_supervisor_fa.operational_api.mission_invalidity_Id, Mining_Threat_Retreat_Supervisor.Mission_Invalidity_Facts_Payload(value))
  }

  // setter for in DataPort
  def put_threat_invalidity(value : Mining_Threat_Retreat_Supervisor.Threat_Invalidity): Unit = {
    Art.insertInInfrastructurePort(Arch.Mining_Threat_Retreat_Supervisor_Root_Instance_supervisor_fa.operational_api.threat_invalidity_Id, Mining_Threat_Retreat_Supervisor.Threat_Invalidity_Payload(value))
  }

  // setter for in DataPort
  def put_resource_invalidity(value : Mining_Threat_Retreat_Supervisor.Resource_Invalidity): Unit = {
    Art.insertInInfrastructurePort(Arch.Mining_Threat_Retreat_Supervisor_Root_Instance_supervisor_fa.operational_api.resource_invalidity_Id, Mining_Threat_Retreat_Supervisor.Resource_Invalidity_Payload(value))
  }

  // setter for in DataPort
  def put_phase_context(value : Mining_Threat_Retreat_Supervisor.Phase_Context): Unit = {
    Art.insertInInfrastructurePort(Arch.Mining_Threat_Retreat_Supervisor_Root_Instance_supervisor_fa.operational_api.phase_context_Id, Mining_Threat_Retreat_Supervisor.Phase_Context_Payload(value))
  }

  // getter for out DataPort
  def get_fault(): Option[Mining_Threat_Retreat_Supervisor.Fault_Fact] = {
    val value: Option[Mining_Threat_Retreat_Supervisor.Fault_Fact] = get_fault_payload() match {
      case Some(Mining_Threat_Retreat_Supervisor.Fault_Fact_Payload(v)) => Some(v)
      case Some(v) => halt(s"Unexpected payload on port fault.  Expecting 'Mining_Threat_Retreat_Supervisor.Fault_Fact_Payload' but received ${v}")
      case _ => None[Mining_Threat_Retreat_Supervisor.Fault_Fact]()
    }
    return value
  }

  // payload getter for out DataPort
  def get_fault_payload(): Option[Mining_Threat_Retreat_Supervisor.Fault_Fact_Payload] = {
    return Art.observeOutInfrastructurePort(Arch.Mining_Threat_Retreat_Supervisor_Root_Instance_supervisor_fa.initialization_api.fault_Id).asInstanceOf[Option[Mining_Threat_Retreat_Supervisor.Fault_Fact_Payload]]
  }

}
